var e={tuning:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Procedure guidate di calibrazione. Scegline una qui sotto.`}},pick:{label:{t:0,b:{t:2,i:[{t:3}],s:`Procedura guidata`}}},params:{start:{t:0,b:{t:2,i:[{t:3}],s:`PA iniziale`}},factor:{t:0,b:{t:2,i:[{t:3}],s:`Fattore (PA/mm)`}},height:{t:0,b:{t:2,i:[{t:3}],s:`Altezza (mm)`}}},pa:{title:{t:0,b:{t:2,i:[{t:3}],s:`Pressure Advance`}},step1:{t:0,b:{t:2,i:[{t:3}],s:`1. Pianifica la torre di taratura`}},plan:{t:0,b:{t:2,i:[{t:3}],s:`Pianifica torre`}},command:{t:0,b:{t:2,i:[{t:3}],s:`Esegui questo comando`}},commandHint:{t:0,b:{t:2,i:[{t:3}],s:`Invialo subito prima della stampa (oppure aggiungilo allo start g-code del tuo modello di prova); il PA aumenta gradualmente lungo la torre man mano che stampa.`}},table:{height:{t:0,b:{t:2,i:[{t:3}],s:`Altezza (mm)`}},pa:{t:0,b:{t:2,i:[{t:3}],s:`PA`}}},step2:{t:0,b:{t:2,i:[{t:3}],s:`2. Inserisci l'altezza dal risultato migliore`}},bestHeight:{t:0,b:{t:2,i:[{t:3}],s:`Altezza Z migliore (mm)`}},computed:{t:0,b:{t:2,i:[{t:3,v:`Pressure Advance calcolato: `},{t:4,k:`pa`}]}},applyButton:{t:0,b:{t:2,i:[{t:3}],s:`Applica PA`}},apply:{applied:{t:0,b:{t:2,i:[{t:3,v:`Pressure Advance `},{t:4,k:`value`},{t:3,v:` applicato`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`La stampante è occupata - impossibile applicare ora`}},out_of_range:{t:0,b:{t:2,i:[{t:3,v:`Valore fuori intervallo (max `},{t:4,k:`max`},{t:3,v:`)`}]}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:`Impossibile applicare: `},{t:4,k:`error`}]}}}},retraction:{title:{t:0,b:{t:2,i:[{t:3}],s:`Retrazione`}},params:{start:{t:0,b:{t:2,i:[{t:3}],s:`Lunghezza iniziale (mm)`}},factor:{t:0,b:{t:2,i:[{t:3}],s:`Fattore (mm/mm)`}},height:{t:0,b:{t:2,i:[{t:3}],s:`Altezza (mm)`}}},step1:{t:0,b:{t:2,i:[{t:3}],s:`1. Pianifica la torre di taratura`}},plan:{t:0,b:{t:2,i:[{t:3}],s:`Pianifica torre`}},command:{t:0,b:{t:2,i:[{t:3}],s:`Esegui questo comando`}},commandHint:{t:0,b:{t:2,i:[{t:3}],s:`Invialo subito prima della stampa (oppure aggiungilo allo start g-code del tuo modello di prova); la lunghezza di retrazione aumenta gradualmente lungo la torre man mano che stampa. Richiede [firmware_retraction] configurato.`}},table:{height:{t:0,b:{t:2,i:[{t:3}],s:`Altezza (mm)`}},value:{t:0,b:{t:2,i:[{t:3}],s:`Lunghezza (mm)`}}},step2:{t:0,b:{t:2,i:[{t:3}],s:`2. Inserisci l'altezza dal risultato migliore`}},bestHeight:{t:0,b:{t:2,i:[{t:3}],s:`Altezza Z migliore (mm)`}},computed:{t:0,b:{t:2,i:[{t:3,v:`Lunghezza di retrazione calcolata: `},{t:4,k:`value`},{t:3,v:` mm`}]}},applyButton:{t:0,b:{t:2,i:[{t:3}],s:`Applica retrazione`}},apply:{applied:{t:0,b:{t:2,i:[{t:3,v:`Lunghezza di retrazione `},{t:4,k:`value`},{t:3,v:` mm applicata`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`La stampante è occupata - impossibile applicare ora`}},out_of_range:{t:0,b:{t:2,i:[{t:3,v:`Valore fuori intervallo (max `},{t:4,k:`max`},{t:3,v:`)`}]}},no_firmware_retraction:{t:0,b:{t:2,i:[{t:3}],s:`Nessuna sezione [firmware_retraction] è configurata su questa stampante`}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:`Impossibile applicare: `},{t:4,k:`error`}]}}}},temp:{title:{t:0,b:{t:2,i:[{t:3}],s:`Temperatura`}},params:{start:{t:0,b:{t:2,i:[{t:3}],s:`Temperatura iniziale (°C)`}},factor:{t:0,b:{t:2,i:[{t:3}],s:`Fattore (°C/mm)`}},band:{t:0,b:{t:2,i:[{t:3}],s:`Altezza della fascia (mm)`}},height:{t:0,b:{t:2,i:[{t:3}],s:`Altezza (mm)`}},heater:{t:0,b:{t:2,i:[{t:3}],s:`Riscaldatore`}}},heaters:{extruder:{t:0,b:{t:2,i:[{t:3}],s:`Estrusore`}},extruder1:{t:0,b:{t:2,i:[{t:3}],s:`Estrusore 1`}},extruder2:{t:0,b:{t:2,i:[{t:3}],s:`Estrusore 2`}},heater_bed:{t:0,b:{t:2,i:[{t:3}],s:`Piano`}}},step1:{t:0,b:{t:2,i:[{t:3}],s:`1. Pianifica la torre di temperatura`}},plan:{t:0,b:{t:2,i:[{t:3}],s:`Pianifica torre`}},command:{t:0,b:{t:2,i:[{t:3}],s:`Esegui questo comando`}},commandHint:{t:0,b:{t:2,i:[{t:3}],s:`Invialo subito prima della stampa (oppure aggiungilo allo start g-code del tuo modello di prova); il target cambia una volta per fascia man mano che la torre sale, dando all'ugello il tempo di stabilizzarsi.`}},table:{range:{t:0,b:{t:2,i:[{t:3}],s:`Intervallo Z (mm)`}},temp:{t:0,b:{t:2,i:[{t:3}],s:`Temperatura (°C)`}}},step2:{t:0,b:{t:2,i:[{t:3}],s:`2. Inserisci l'altezza dal risultato migliore`}},bestHeight:{t:0,b:{t:2,i:[{t:3}],s:`Altezza Z migliore (mm)`}},computed:{t:0,b:{t:2,i:[{t:3,v:`Temperatura migliore: `},{t:4,k:`temp`},{t:3,v:` °C`}]}},noBand:{t:0,b:{t:2,i:[{t:3}],s:`Inserisci un'altezza all'interno della torre`}},applyButton:{t:0,b:{t:2,i:[{t:3}],s:`Imposta temperatura`}},apply:{applied:{t:0,b:{t:2,i:[{t:4,k:`heater`},{t:3,v:` impostato a `},{t:4,k:`value`},{t:3,v:` °C`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`La stampante è occupata - impossibile applicare ora`}},unknown_heater:{t:0,b:{t:2,i:[{t:3}],s:`Riscaldatore sconosciuto`}},out_of_range:{t:0,b:{t:2,i:[{t:3,v:`Valore fuori intervallo (max `},{t:4,k:`max`},{t:3,v:`)`}]}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:`Impossibile applicare: `},{t:4,k:`error`}]}}}},flow:{title:{t:0,b:{t:2,i:[{t:3}],s:`Flusso`}},step1:{t:0,b:{t:2,i:[{t:3}],s:`1. Estrudi una lunghezza nota, poi misura quanto è effettivamente uscito`}},requested:{t:0,b:{t:2,i:[{t:3}],s:`Lunghezza comandata (mm)`}},measured:{t:0,b:{t:2,i:[{t:3}],s:`Lunghezza misurata (mm)`}},current:{t:0,b:{t:2,i:[{t:3}],s:`rotation_distance attuale`}},fetch:{t:0,b:{t:2,i:[{t:3}],s:`Leggi dalla stampante`}},calc:{t:0,b:{t:2,i:[{t:3}],s:`Calcola`}},step2:{t:0,b:{t:2,i:[{t:3}],s:`2. Correzione`}},result:{t:0,b:{t:2,i:[{t:3,v:`Nuovo rotation_distance: `},{t:4,k:`value`}]}},flowPercent:{t:0,b:{t:2,i:[{t:3,v:`Flusso equivalente nello slicer: `},{t:4,k:`percent`},{t:3,v:`%`}]}},snippetTitle:{t:0,b:{t:2,i:[{t:3}],s:`Incolla nella tua sezione [extruder], poi esegui SAVE_CONFIG e riavvia`}},notLive:{t:0,b:{t:2,i:[{t:3}],s:`Il flusso non può essere impostato dal vivo - applicalo con un salvataggio della configurazione e un riavvio, non istantaneamente.`}},noCurrent:{t:0,b:{t:2,i:[{t:3}],s:`Impossibile leggerlo dalla stampante - inserisci manualmente il rotation_distance della tua sezione [extruder].`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Guida`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Guida alle procedure di taratura`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Chiudi`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è il Pressure Advance?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Il PA compensa il ritardo di pressione nell'ugello, rendendo gli angoli più netti e riducendo colature e rigonfiamenti. Ogni filamento ha il proprio valore ottimale.`}}},workflow:{title:{t:0,b:{t:2,i:[{t:3}],s:`Come funzionano le procedure guidate`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Pianifica una torre di taratura, stampala (il valore aumenta man mano che sale), individua l'altezza più pulita, poi applica il valore corrispondente. Salvalo in printer.cfg per mantenerlo.`}}},retraction:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è la retrazione?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`La retrazione richiama il filamento durante gli spostamenti per evitare colature e filamenti sottili. Troppo poca lascia filamenti; troppa può causare intasamenti o vuoti. Questa procedura guidata regola la lunghezza di retrazione del firmware.`}}},temperature:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è una torre di temperatura?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Una torre di temperatura stampa la stessa forma a temperature dell'ugello crescenti, così puoi scegliere quella con la migliore adesione tra i layer, la finitura superficiale migliore e meno filamenti per il tuo filamento.`}}},flow:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è la calibrazione del flusso?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`La calibrazione del flusso corregge la quantità di filamento che l'estrusore spinge effettivamente. Comanda una lunghezza nota, misura quanto è uscito e la procedura guidata regola il rotation_distance. Klipper non ha un'impostazione del flusso dal vivo, quindi il nuovo valore va in printer.cfg.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glossario`}}}},glossary:{pressureAdvance:{term:{t:0,b:{t:2,i:[{t:3}],s:`Pressure Advance`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Un'impostazione di Klipper che regola l'estrusione in anticipo rispetto ai cambi di velocità per ottenere angoli più netti.`}}},tuningTower:{term:{t:0,b:{t:2,i:[{t:3}],s:`Torre di taratura`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Una stampa alta in cui TUNING_TOWER modifica progressivamente un parametro con l'altezza, così puoi scegliere il layer migliore.`}}},firmwareRetraction:{term:{t:0,b:{t:2,i:[{t:3}],s:`Retrazione del firmware`}},def:{t:0,b:{t:2,i:[{t:3}],s:`La funzione [firmware_retraction] di Klipper: G10/G11 per retrarre e ritrarre gestiti dalla stampante, regolabili dal vivo con SET_RETRACTION.`}}},temperatureTower:{term:{t:0,b:{t:2,i:[{t:3}],s:`Torre di temperatura`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Una stampa di prova suddivisa in fasce, ciascuna mantenuta a una diversa temperatura dell'ugello, per trovare la temperatura di stampa migliore di un filamento.`}}},rotationDistance:{term:{t:0,b:{t:2,i:[{t:3}],s:`rotation_distance`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Quanti mm di filamento l'estrusore alimenta per ogni rotazione del motore. Abbassarlo spinge più filamento; la calibrazione del flusso regola questo valore.`}}}}}}};export{e as default};